def _evidence(context: dict, section: int) -> str:
    aspects = context.get("themes", {}).get(SECTION_THEME[section], [])[:2]
    if not aspects:
        aspects = context.get("strongest_aspects", [])[:1]
    if not aspects:
        return ""
    labels = []
    for item in aspects:
        left = PLANET_UA.get(item.get("planet_a"), item.get("planet_a", "планета А"))
        right = PLANET_UA.get(item.get("planet_b"), item.get("planet_b", "планета Б"))
        aspect = ASPECT_UA.get(item.get("aspect"), item.get("aspect", "аспект"))
        orb = item.get("orb", 0)
        labels.append(f"{left} першої карти — {aspect} — {right} другої карти (орбіс {orb:.1f}°)")
    return "У вашому розрахунку цю тему підтримують конкретні контакти: " + "; ".join(labels) + ". Чим менший орбіс, тим точніше й помітніше працює контакт, але його прояв залежить від ваших реальних рішень і навичок."


def deepen_together_text(text: str, context: dict) -> str:
    header = re.compile(r"(Секція\s+(\d{1,2})\.[^\n]*\n)", re.IGNORECASE)
    parts = header.split(text)
    if len(parts) < 4:
        return text
    output = [parts[0]]
    index = 1
    while index + 2 < len(parts):
        heading, number_text, body = parts[index], parts[index + 1], parts[index + 2]
        number = int(number_text)
        addition = "\n\n".join(value for value in (_evidence(context, number), EXPANSIONS.get(number, "")) if value)
        output.extend([heading, body.rstrip() + "\n\n" + addition + "\n\n"])
        index += 3
    return "".join(output).rstrip()
